@Override
public void visitResourceFolder(@NonNull ResourceContext context, @NonNull File folder) {
    ResourceFolderType type = context.getResourceFolderType();
    if (type != ResourceFolderType.DRAWABLE && type != ResourceFolderType.MIPMAP) {
        return;
    }

    FolderConfiguration config = context.getFolderConfiguration();
    DensityQualifier densityQualifier = config.getDensityQualifier();
    if (densityQualifier == null) {
        return;
    }
    Density density = densityQualifier.getValue();
    if (density == Density.NODPI || density == Density.ANYDPI) {
        return;
    }

    File[] files = folder.listFiles();
    if (files == null) {
        return;
    }

    for (File file : files) {
        String name = file.getName();
        // Skip non-image files and 9-patches
        if (!isImageFile(name)) {
            continue;
        }

        String baseName = getBaseName(name);
        String key = type.getName() + "/" + baseName;

        Multimap<Density, File> map = mIcons.get(key);
        if (map == null) {
            map = ArrayListMultimap.create();
            mIcons.put(key, map);
        }
        map.put(density, file);
    }
}
```

