@Override
public void afterCheckEachProject(@NonNull Context context) {
    boolean includeLdpi = Boolean.parseBoolean(
        System.getenv("ANDROID_LINT_INCLUDE_LDPI"));

    Set<Density> expectedDensities = EnumSet.of(
        Density.MEDIUM, Density.HIGH, Density.XHIGH, Density.XXHIGH, Density.XXXHIGH
    );
    if (includeLdpi) {
        expectedDensities.add(Density.LOW);
    }

    for (Map.Entry<String, Multimap<Density, File>> entry : mIcons.entrySet()) {
        Multimap<Density, File> densities = entry.getValue();
        Set<Density> present = densities.keySet();

        // Only check icons that have at least one density-specific version
        // and are missing some densities
        Set<Density> missing = Sets.newEnumSet(expectedDensities, Density.class);
        missing.removeAll(present);

        if (!missing.isEmpty() && !present.isEmpty()) {
            // Report on the first file
            File file = densities.values().iterator().next();
            String message = String.format(
                "Missing the following density variations of this icon: %s",
                missing
            );
            context.report(ICON_DENSITIES, Location.create(file), message);
        }
    }

    mIcons = null;
}
```

